#include <stdio.h>

int main() {
    int burst[] = {4, 2, 6};
    int wait = 0;
    for (int i = 0; i < 3; i++) {
        printf("P%d waits %d\n", i + 1, wait);
        wait += burst[i];
    }
    return 0;
}
